-- PMOS AUX-V1 unified table; all source fields are preserved in record_json/raw_json.
-- Only creates epf_pmos_aux_records; never modifies epf_pmos_96_full.
CREATE TABLE IF NOT EXISTS epf_pmos_aux_records (
  id BIGINT NOT NULL AUTO_INCREMENT,
  record_key CHAR(64) NOT NULL COMMENT 'raw=request_key+raw_hash, structured=parser business key',
  run_id VARCHAR(64) DEFAULT NULL,
  record_kind VARCHAR(16) NOT NULL COMMENT 'raw or structured',
  source_group VARCHAR(32) DEFAULT NULL,
  source_name VARCHAR(64) DEFAULT NULL,
  record_type VARCHAR(64) DEFAULT NULL,
  business_date DATE DEFAULT NULL,
  resolution VARCHAR(32) DEFAULT NULL,
  source_api VARCHAR(512) DEFAULT NULL,
  request_key CHAR(64) DEFAULT NULL,
  request_params_json TEXT,
  http_status INT DEFAULT NULL,
  business_code VARCHAR(32) DEFAULT NULL,
  source_status VARCHAR(32) DEFAULT NULL,
  source_row_count INT DEFAULT NULL,
  raw_hash CHAR(64) DEFAULT NULL,
  raw_json LONGTEXT,
  record_json LONGTEXT COMMENT '完整保留 parser 输出的业务字段，不丢失来源原字段名',
  captured_at DATETIME DEFAULT NULL,
  schema_version VARCHAR(32) NOT NULL DEFAULT 'AUX-V1',
  create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  UNIQUE KEY uk_aux_record_key (record_key),
  KEY idx_aux_date_source (business_date, source_name),
  KEY idx_aux_kind_status (record_kind, source_status),
  KEY idx_aux_run (run_id),
  KEY idx_aux_request (request_key),
  KEY idx_aux_captured (captured_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='PMOS辅助披露统一原始与结构化记录表';
